import { compose } from '@adonisjs/core/helpers'
import { BaseModel, column } from '@adonisjs/lucid/orm'
import { test } from '@japa/runner'
import { withRoleModel } from '../src/mixins/with_role_model.ts'
import { Member, permissions, Role, TeamMember, User } from './fixtures/models.ts'
import { setupDatabase } from './helpers.ts'

/**
 * A schema class booted by its own decorators, as generated by the
 * Lucid schema generator.
 */
class UserSchema extends BaseModel {
  static table = 'users'

  @column({ isPrimary: true })
  declare id: number

  @column()
  declare email: string

  @column()
  declare permissions: string
}

/**
 * User model built on top of an already booted schema class.
 */
class SchemaUser extends compose(
  UserSchema,
  withRoleModel(permissions, {
    role: () => Role,
    pivotTable: 'user_roles',
    pivotForeignKey: 'user_id',
  })
) {
  static table = 'users'
}

type Database = Awaited<ReturnType<typeof setupDatabase>>

/**
 * Returns the role ids assigned to a user, as stored in the pivot table.
 */
async function pivotRoleIds(database: Database, userId: number): Promise<number[]> {
  const rows = await database.db
    .from('user_roles')
    .where('user_id', userId)
    .orderBy('role_id')
    .select('role_id')
  return rows.map((row) => row.role_id)
}

/**
 * Creates the editor, billing and admin roles.
 */
async function seedRoles() {
  const editor = await Role.create({ name: 'editor' })
  await editor.givePermissions(['product.create', 'product.update'])

  const billing = await Role.create({ name: 'billing' })
  await billing.givePermissions(['billing.refund'])

  const admin = await Role.create({ name: 'admin' })
  await admin.givePermissions(['*'])

  return { editor, billing, admin }
}

test.group('withRoleModel', (group) => {
  let database: Database

  group.each.setup(async () => {
    database = await setupDatabase()
    return () => database.close()
  })

  test('assigns roles by row and by id', async ({ assert }) => {
    const { editor, billing } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })

    await user.assignRole(editor)
    await user.assignRoles([billing.id])

    assert.deepEqual(await pivotRoleIds(database, user.id), [editor.id, billing.id])
    assert.deepEqual(
      (await user.getRoles()).map((role) => role.name),
      ['editor', 'billing']
    )
  })

  test('assigns roles idempotently despite the unique pivot constraint', async ({ assert }) => {
    const { editor, billing } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })

    await user.assignRole(editor)
    await user.assignRole(editor)
    await user.assignRoles([editor, editor.id, billing])
    await user.assignRoles([])

    assert.deepEqual(await pivotRoleIds(database, user.id), [editor.id, billing.id])
  })

  test('syncs roles', async ({ assert }) => {
    const { editor, billing, admin } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })
    await user.assignRoles([editor, billing])

    await user.syncRoles([billing, admin])
    assert.deepEqual(await pivotRoleIds(database, user.id), [billing.id, admin.id])

    await user.syncRoles([billing, admin])
    assert.deepEqual(await pivotRoleIds(database, user.id), [billing.id, admin.id])

    await user.syncRoles([])
    assert.deepEqual(await pivotRoleIds(database, user.id), [])
  })

  test('revokes roles idempotently', async ({ assert }) => {
    const { editor, billing, admin } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })
    await user.assignRoles([editor, billing, admin])

    await user.revokeRole(editor)
    await user.revokeRoles([billing.id])
    await user.revokeRole(editor)
    await user.revokeRoles([])

    assert.deepEqual(await pivotRoleIds(database, user.id), [admin.id])
  })

  test('only touches the pivot rows of the mutated user', async ({ assert }) => {
    const { editor, billing } = await seedRoles()
    const virk = await User.create({ email: 'virk@adonisjs.com' })
    const romain = await User.create({ email: 'romain@adonisjs.com' })
    await virk.assignRoles([editor, billing])
    await romain.assignRoles([editor, billing])

    await virk.syncRoles([billing])
    await virk.revokeRole(billing)

    assert.deepEqual(await pivotRoleIds(database, virk.id), [])
    assert.deepEqual(await pivotRoleIds(database, romain.id), [editor.id, billing.id])
  })

  test('checks role membership by name and by row', async ({ assert }) => {
    const { editor, billing } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })
    await user.assignRole(editor)

    assert.isTrue(await user.hasRole('editor'))
    assert.isFalse(await user.hasRole('billing'))
    assert.isFalse(await user.hasRole('unknown'))
    assert.isTrue(await user.hasRole(editor))
    assert.isTrue(await user.hasRole(await Role.findOrFail(editor.id)))
    assert.isFalse(await user.hasRole(billing))
  })

  test('aggregates permissions from every role', async ({ assert }) => {
    const { editor, billing } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })
    await user.assignRoles([editor, billing])

    assert.deepEqual(await user.getGrants(), ['product.create', 'product.update', 'billing.refund'])
    assert.deepEqual(await user.getPermissions(), [
      'product.create',
      'product.update',
      'billing.refund',
    ])
    assert.isTrue(await user.hasPermission('billing.refund'))
    assert.isFalse(await user.hasPermission('product.delete'))
  })

  test('expands a wildcard role to permissions defined after it was stored', async ({ assert }) => {
    const { admin } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })
    await user.assignRole(admin)

    assert.deepEqual(await user.getPermissions(), [
      'product.create',
      'product.update',
      'product.delete',
      'billing.refund',
      'admin.user.ban',
      'admin.user.impersonate',
    ])
  })

  test('reuses preloaded roles without querying', async ({ assert }) => {
    const { editor, billing } = await seedRoles()
    const created = await User.create({ email: 'virk@adonisjs.com' })
    await created.assignRoles([editor, billing])

    const user = await User.query().where('id', created.id).preload('roles').firstOrFail()

    const { result, queries } = await database.track(async () => ({
      roles: (await user.getRoles()).map((role) => role.name),
      editor: await user.hasRole('editor'),
      permissions: await user.getPermissions(),
    }))

    assert.lengthOf(queries, 0)
    assert.deepEqual(result, {
      roles: ['editor', 'billing'],
      editor: true,
      permissions: ['product.create', 'product.update', 'billing.refund'],
    })
  })

  test('queries roles when they are not preloaded', async ({ assert }) => {
    const { editor } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })
    await user.assignRole(editor)

    const { result, queries } = await database.track(() => user.getRoles())

    assert.lengthOf(queries, 1)
    assert.include(queries[0].sql, '`user_roles`')
    assert.deepEqual(
      result.map((role) => role.name),
      ['editor']
    )
  })

  test('invalidates preloaded roles after {title}')
    .with([
      {
        title: 'assignRole',
        mutate: (user: User, roles: Awaited<ReturnType<typeof seedRoles>>) =>
          user.assignRole(roles.admin),
        expected: ['editor', 'admin'],
      },
      {
        title: 'syncRoles',
        mutate: (user: User, roles: Awaited<ReturnType<typeof seedRoles>>) =>
          user.syncRoles([roles.billing]),
        expected: ['billing'],
      },
      {
        title: 'revokeRole',
        mutate: (user: User, roles: Awaited<ReturnType<typeof seedRoles>>) =>
          user.revokeRole(roles.editor),
        expected: [],
      },
    ])
    .run(async ({ assert }, { mutate, expected }) => {
      const roles = await seedRoles()
      const created = await User.create({ email: 'virk@adonisjs.com' })
      await created.assignRole(roles.editor)

      const user = await User.query().where('id', created.id).preload('roles').firstOrFail()
      assert.isTrue(user.$hasRelated('roles'))

      await mutate(user, roles)

      assert.isFalse(user.$hasRelated('roles'))
      assert.deepEqual(
        (await user.getRoles()).map((role) => role.name),
        expected
      )
    })

  test('queries users through the roles relationship', async ({ assert }) => {
    const { editor, admin } = await seedRoles()
    const virk = await User.create({ email: 'virk@adonisjs.com' })
    const romain = await User.create({ email: 'romain@adonisjs.com' })
    await User.create({ email: 'julien@adonisjs.com' })
    await virk.assignRole(admin)
    await romain.assignRole(editor)

    const admins = await User.query().whereHas('roles', (query) => {
      query.where('name', 'admin')
    })
    assert.deepEqual(
      admins.map((user) => user.email),
      ['virk@adonisjs.com']
    )

    const withRoleModel = await User.query().has('roles').orderBy('id')
    assert.deepEqual(
      withRoleModel.map((user) => user.email),
      ['virk@adonisjs.com', 'romain@adonisjs.com']
    )
  })

  test('registers the relationship on top of an already booted schema class', async ({
    assert,
  }) => {
    assert.isTrue(UserSchema.booted)
    const { editor } = await seedRoles()

    const user = await SchemaUser.create({ email: 'virk@adonisjs.com', permissions: '[]' })
    await user.assignRole(editor)

    const loaded = await SchemaUser.query().where('id', user.id).preload('roles').firstOrFail()
    assert.deepEqual(
      loaded.roles.map((role) => role.name),
      ['editor']
    )
    assert.deepEqual(await loaded.getPermissions(), ['product.create', 'product.update'])
  })

  test('deleting a role cascades to the pivot table', async ({ assert }) => {
    const { editor, billing } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })
    await user.assignRoles([editor, billing])

    await editor.delete()

    assert.deepEqual(await pivotRoleIds(database, user.id), [billing.id])
  })
})

test.group('withRoleModel | composition', (group) => {
  let database: Database

  group.each.setup(async () => {
    database = await setupDatabase()
    return () => database.close()
  })

  test('merges direct and role grants with withPermissions applied first', async ({ assert }) => {
    const { editor } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })
    await user.assignRole(editor)
    await user.givePermissions(['billing.refund', 'product.create'])

    assert.deepEqual(await user.getGrants(), ['billing.refund', 'product.create', 'product.update'])
    assert.deepEqual(await user.getPermissions(), [
      'product.create',
      'product.update',
      'billing.refund',
    ])

    const raw = await database.db.from('users').where('id', user.id).firstOrFail()
    assert.equal(raw.permissions, '["billing.refund","product.create"]')
  })

  test('merges direct and role grants with withRoleModel applied first', async ({ assert }) => {
    const { editor } = await seedRoles()
    const member = await Member.create({})
    await member.assignRole(editor)
    await member.givePermission('admin.user.ban')

    assert.deepEqual(await member.getGrants(), [
      'product.create',
      'product.update',
      'admin.user.ban',
    ])
    assert.deepEqual(await member.getPermissions(), [
      'product.create',
      'product.update',
      'admin.user.ban',
    ])
    assert.isTrue(await member.hasPermission('admin.user.ban'))
    assert.isTrue(await member.hasRole('editor'))

    const pivot = await database.db.from('member_roles').select('member_id', 'role_id')
    assert.deepEqual(pivot, [{ member_id: member.id, role_id: editor.id }])
  })

  test('supports custom pivot columns for team members', async ({ assert }) => {
    const { editor, admin } = await seedRoles()
    const teamA = await TeamMember.create({ teamId: 1, userId: 7 })
    const teamB = await TeamMember.create({ teamId: 2, userId: 7 })

    await teamA.assignRole(editor)
    await teamB.assignRoles([admin, editor])
    await teamB.revokeRole(editor)

    const pivot = await database.db
      .from('team_member_roles')
      .orderBy('id')
      .select('membership_id', 'granted_role_id')
    assert.deepEqual(pivot, [
      { membership_id: teamA.id, granted_role_id: editor.id },
      { membership_id: teamB.id, granted_role_id: admin.id },
    ])

    assert.deepEqual(await teamA.getPermissions(), ['product.create', 'product.update'])
    assert.isTrue(await teamB.hasPermission('admin.user.ban'))
    assert.isFalse(await teamA.hasPermission('admin.user.ban'))

    const loaded = await TeamMember.query()
      .where('teamId', 2)
      .where('userId', 7)
      .preload('roles')
      .firstOrFail()
    assert.deepEqual(
      loaded.roles.map((role) => role.name),
      ['admin']
    )
  })

  test('mutations use the transaction of the row and roll back', async ({ assert }) => {
    const { editor, billing } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })
    await user.assignRole(billing)
    await user.givePermission('product.create')

    const trx = await database.db.transaction()
    user.useTransaction(trx)

    await user.assignRole(editor)
    await user.revokeRole(billing)
    await user.givePermission('admin.*')
    assert.deepEqual(await user.getPermissions(), [
      'product.create',
      'product.update',
      'admin.user.ban',
      'admin.user.impersonate',
    ])

    await trx.rollback()

    assert.deepEqual(await pivotRoleIds(database, user.id), [billing.id])
    const raw = await database.db.from('users').where('id', user.id).firstOrFail()
    assert.equal(raw.permissions, '["product.create"]')

    const fresh = await User.findOrFail(user.id)
    assert.deepEqual(await fresh.getPermissions(), ['product.create', 'billing.refund'])
  })

  test('mutations commit with the transaction of the row', async ({ assert }) => {
    const { editor } = await seedRoles()
    const user = await User.create({ email: 'virk@adonisjs.com' })

    const trx = await database.db.transaction()
    user.useTransaction(trx)
    await user.assignRole(editor)
    await user.givePermission('billing.refund')
    await trx.commit()

    assert.deepEqual(await pivotRoleIds(database, user.id), [editor.id])
    const fresh = await User.findOrFail(user.id)
    assert.deepEqual(await fresh.getPermissions(), [
      'product.create',
      'product.update',
      'billing.refund',
    ])
  })
})
